1  import {Str} from 'expensify-common';
     2  import lodashMapValues from 'lodash/mapValues';
     3  import lodashSortBy from 'lodash/sortBy';
     4  import type {ForwardedRef} from 'react';
     5  import React, {forwardRef, useCallback, useEffect, useImperativeHandle, useMemo, useRef, useState} from 'react';
     6  import type {OnyxCollection} from 'react-native-onyx';
     7  import {useOnyx} from 'react-native-onyx';
     8  import * as Expensicons from '@components/Icon/Expensicons';
     9  import type {Mention} from '@components/MentionSuggestions';
    10  import MentionSuggestions from '@components/MentionSuggestions';
    11  import {usePersonalDetails} from '@components/OnyxProvider';
    12  import useArrowKeyFocusManager from '@hooks/useArrowKeyFocusManager';
    13  import useCurrentReportID from '@hooks/useCurrentReportID';
    14  import useCurrentUserPersonalDetails from '@hooks/useCurrentUserPersonalDetails';
    15  import useDebounce from '@hooks/useDebounce';
    16  import useLocalize from '@hooks/useLocalize';
    17  import localeCompare from '@libs/LocaleCompare';
    18  import * as LoginUtils from '@libs/LoginUtils';
    19  import * as PersonalDetailsUtils from '@libs/PersonalDetailsUtils';
    20  import getPolicyEmployeeAccountIDs from '@libs/PolicyEmployeeListUtils';
    21  import * as ReportUtils from '@libs/ReportUtils';
    22  import * as SuggestionsUtils from '@libs/SuggestionUtils';
    23  import {isValidRoomName} from '@libs/ValidationUtils';
    24  import * as ReportUserActions from '@userActions/Report';
    25  import CONST from '@src/CONST';
    26  import ONYXKEYS from '@src/ONYXKEYS';
    27  import type {PersonalDetails, PersonalDetailsList, Report} from '@src/types/onyx';
    28  import type {SuggestionsRef} from './ReportActionCompose';
    29  import type {SuggestionProps} from './Suggestions';
    30
    31  type SuggestionValues = {
    32      suggestedMentions: Mention[];
    33      atSignIndex: number;
    34      shouldShowSuggestionMenu: boolean;
    35      mentionPrefix: string;
    36      prefixType: string;
    37  };
    38
    39  /**
    40   * Check if this piece of string looks like a mention
    41   */
    42  const isMentionCode = (str: string): boolean => CONST.REGEX.HAS_AT_MOST_TWO_AT_SIGNS.test(str);
    43
    44  const defaultSuggestionsValues: SuggestionValues = {
    45      suggestedMentions: [],
    46      atSignIndex: -1,
    47      shouldShowSuggestionMenu: false,
    48      mentionPrefix: '',
    49      prefixType: '',
    50  };
    51
    52  type SuggestionPersonalDetailsList = Record<
    53      string,
    54      | (PersonalDetails & {
    55            weight: number;
    56        })
    57      | null
    58  >;
    59
    60  function getDisplayName(details: PersonalDetails) {
    61      const displayNameFromAccountID = ReportUtils.getDisplayNameForParticipant(details.accountID);
    62      if (!displayNameFromAccountID) {
    63          return details.login?.length ? details.login : '';
    64      }
    65      return displayNameFromAccountID;
    66  }
    67
    68  /**
    69   * Comparison function to sort users. It compares weights, display names, and accountIDs in that order
    70   */
    71  function compareUserInList(first: PersonalDetails & {weight: number}, second: PersonalDetails & {weight: number}) {
    72      if (first.weight !== second.weight) {
    73          return first.weight - second.weight;
    74      }
    75
    76      const displayNameLoginOrder = localeCompare(getDisplayName(first), getDisplayName(second));
    77      if (displayNameLoginOrder !== 0) {
    78          return displayNameLoginOrder;
    79      }
    80
    81      return first.accountID - second.accountID;
    82  }
    83
    84  function SuggestionMention(
    85      {value, selection, setSelection, updateComment, isAutoSuggestionPickerLarge, measureParentContainerAndReportCursor, isComposerFocused, isGroupPolicyReport, policyID}: SuggestionProps,
    86      ref: ForwardedRef<SuggestionsRef>,
    87  ) {
    88      const personalDetails = usePersonalDetails() ?? CONST.EMPTY_OBJECT;
    89      const {translate, formatPhoneNumber} = useLocalize();
    90      const [suggestionValues, setSuggestionValues] = useState(defaultSuggestionsValues);
    91      const suggestionValuesRef = useRef(suggestionValues);
    92      suggestionValuesRef.current = suggestionValues;
    93
    94      const [reports] = useOnyx(ONYXKEYS.COLLECTION.REPORT);
    95
    96      const currentUserPersonalDetails = useCurrentUserPersonalDetails();
    97      const isMentionSuggestionsMenuVisible = !!suggestionValues.suggestedMentions.length && suggestionValues.shouldShowSuggestionMenu;
    98
    99      const currentReportID = useCurrentReportID();
   100      const currentReport = reports?.[`${ONYXKEYS.COLLECTION.REPORT}${currentReportID?.currentReportID}`];
   101      // Smaller weight means higher order in suggestion list
   102      const getPersonalDetailsWeight = useCallback(
   103          (detail: PersonalDetails, policyEmployeeAccountIDs: number[]): number => {
   104              if (ReportUtils.isReportParticipant(detail.accountID, currentReport)) {
   105                  return 0;
   106              }
   107              if (policyEmployeeAccountIDs.includes(detail.accountID)) {
   108                  return 1;
   109              }
   110              return 2;
   111          },
   112          [currentReport],
   113      );
   114      const weightedPersonalDetails: PersonalDetailsList | SuggestionPersonalDetailsList = useMemo(() => {
   115          const policyEmployeeAccountIDs = getPolicyEmployeeAccountIDs(policyID);
   116          if (!ReportUtils.isGroupChat(currentReport) && !ReportUtils.doesReportBelongToWorkspace(currentReport, policyEmployeeAccountIDs, policyID)) {
   117              return personalDetails;
   118          }
   119          return lodashMapValues(personalDetails, (detail) =>
   120              detail
   121                  ? {
   122                        ...detail,
   123                        weight: getPersonalDetailsWeight(detail, policyEmployeeAccountIDs),
   124                    }
   125                  : null,
   126          );
   127      }, [policyID, currentReport, personalDetails, getPersonalDetailsWeight]);
   128
   129      const [highlightedMentionIndex, setHighlightedMentionIndex] = useArrowKeyFocusManager({
   130          isActive: isMentionSuggestionsMenuVisible,
   131          maxIndex: suggestionValues.suggestedMentions.length - 1,
   132          shouldExcludeTextAreaNodes: false,
   133      });
   134
   135      // Used to store the selection index of the last inserted mention
   136      const suggestionInsertionIndexRef = useRef<number | null>(null);
   137
   138      // Used to detect if the selection has changed since the last suggestion insertion
   139      // If so, we reset the suggestionInsertionIndexRef
   140      const hasSelectionChanged = !(selection.end === selection.start && selection.start === suggestionInsertionIndexRef.current);
   141      if (hasSelectionChanged) {
   142          suggestionInsertionIndexRef.current = null;
   143      }
   144
   145      // Used to decide whether to block the suggestions list from showing to prevent flickering
   146      const shouldBlockCalc = useRef(false);
   147
   148      /**
   149       * Search for reports suggestions in server.
   150       *
   151       * The function is debounced to not perform requests on every keystroke.
   152       */
   153      const debouncedSearchInServer = useDebounce(
   154          useCallback(() => {
   155              const foundSuggestionsCount = suggestionValues.suggestedMentions.length;
   156              if (suggestionValues.prefixType === '#' && foundSuggestionsCount < 5 && isGroupPolicyReport) {
   157                  ReportUserActions.searchInServer(value, policyID);
   158              }
   159          }, [suggestionValues.suggestedMentions.length, suggestionValues.prefixType, policyID, value, isGroupPolicyReport]),
   160          CONST.TIMING.SEARCH_OPTION_LIST_DEBOUNCE_TIME,
   161      );
   162
   163      const formatLoginPrivateDomain = useCallback(
   164          (displayText = '', userLogin = '') => {
   165              if (userLogin !== displayText) {
   166                  return displayText;
   167              }
   168              // If the emails are not in the same private domain, we also return the displayText
   169              if (!LoginUtils.areEmailsFromSamePrivateDomain(displayText, currentUserPersonalDetails.login ?? '')) {
   170                  return Str.removeSMSDomain(displayText);
   171              }
   172
   173              // Otherwise, the emails must be of the same private domain, so we should remove the domain part
   174              return displayText.split('@')[0];
   175          },
   176          [currentUserPersonalDetails.login],
   177      );
   178
   179      const getMentionCode = useCallback(
   180          (mention: Mention, mentionType: string): string => {
   181              if (mentionType === '#') {
   182                  // room mention case
   183                  return mention.handle ?? '';
   184              }
   185              return mention.text === CONST.AUTO_COMPLETE_SUGGESTER.HERE_TEXT ? CONST.AUTO_COMPLETE_SUGGESTER.HERE_TEXT : `@${formatLoginPrivateDomain(mention.handle, mention.handle)}`;
   186          },
   187          [formatLoginPrivateDomain],
   188      );
   189
   190      /**
   191       * Replace the code of mention and update selection
   192       */
   193      const insertSelectedMention = useCallback(
   194          (highlightedMentionIndexInner: number) => {
   195              const commentBeforeAtSign = value.slice(0, suggestionValues.atSignIndex);
   196              const mentionObject = suggestionValues.suggestedMentions[highlightedMentionIndexInner];
   197              const mentionCode = getMentionCode(mentionObject, suggestionValues.prefixType);
   198              const commentAfterAtSignWithMentionRemoved = value.slice(suggestionValues.atSignIndex).replace(CONST.REGEX.MENTION_REPLACER, '');
   199              updateComment(`${commentBeforeAtSign}${mentionCode} ${SuggestionsUtils.trimLeadingSpace(commentAfterAtSignWithMentionRemoved)}`, true);
   200              const selectionPosition = suggestionValues.atSignIndex + mentionCode.length + CONST.SPACE_LENGTH;
   201              setSelection({
   202                  start: selectionPosition,
   203                  end: selectionPosition,
   204              });
   205              suggestionInsertionIndexRef.current = selectionPosition;
   206              setSuggestionValues((prevState) => ({
   207                  ...prevState,
   208                  suggestedMentions: [],
   209                  shouldShowSuggestionMenu: false,
   210              }));
   211          },
   212          [value, suggestionValues.atSignIndex, suggestionValues.suggestedMentions, updateComment, setSelection],
   213      );
   214
   215      /**
   216       * Clean data related to suggestions
   217       */
   218      const resetSuggestions = useCallback(() => {
   219          setSuggestionValues(defaultSuggestionsValues);
   220      }, []);
   221
   222      /**
   223       * Listens for keyboard shortcuts and applies the action
   224       */
   225      const triggerHotkeyActions = useCallback(
   226          (event: KeyboardEvent) => {
   227              const suggestionsExist = suggestionValues.suggestedMentions.length > 0;
   228
   229              if (((!event.shiftKey && event.key === CONST.KEYBOARD_SHORTCUTS.ENTER.shortcutKey) || event.key === CONST.KEYBOARD_SHORTCUTS.TAB.shortcutKey) && suggestionsExist) {
   230                  event.preventDefault();
   231                  if (suggestionValues.suggestedMentions.length > 0) {
   232                      insertSelectedMention(highlightedMentionIndex);
   233                      return true;
   234                  }
   235              }
   236
   237              if (event.key === CONST.KEYBOARD_SHORTCUTS.ESCAPE.shortcutKey) {
   238                  event.preventDefault();
   239
   240                  if (suggestionsExist) {
   241                      resetSuggestions();
   242                  }
   243
   244                  return true;
   245              }
   246          },
   247          [highlightedMentionIndex, insertSelectedMention, resetSuggestions, suggestionValues.suggestedMentions.length],
   248      );
   249
   250      const getUserMentionOptions = useCallback(
   251          (personalDetailsParam: PersonalDetailsList | SuggestionPersonalDetailsList, searchValue = ''): Mention[] => {
   252              const suggestions = [];
   253
   254              if (CONST.AUTO_COMPLETE_SUGGESTER.HERE_TEXT.includes(searchValue.toLowerCase())) {
   255                  suggestions.push({
   256                      text: CONST.AUTO_COMPLETE_SUGGESTER.HERE_TEXT,
   257                      alternateText: translate('mentionSuggestions.hereAlternateText'),
   258                      icons: [
   259                          {
   260                              source: Expensicons.Megaphone,
   261                              type: CONST.ICON_TYPE_AVATAR,
   262                          },
   263                      ],
   264                  });
   265              }
   266
   267              const filteredPersonalDetails = Object.values(personalDetailsParam ?? {}).filter((detail) => {
   268                  // If we don't have user's primary login, that member is not known to the current user and hence we do not allow them to be mentioned
   269                  if (!detail?.login || detail.isOptimisticPersonalDetail) {
   270                      return false;
   271                  }
   272                  // We don't want to mention system emails like notifications@expensify.com
   273                  if (CONST.RESTRICTED_EMAILS.includes(detail.login) || CONST.RESTRICTED_ACCOUNT_IDS.includes(detail.accountID)) {
   274                      return false;
   275                  }
   276                  const displayName = PersonalDetailsUtils.getDisplayNameOrDefault(detail);
   277                  const displayText = displayName === formatPhoneNumber(detail.login) ? displayName : `${displayName} ${detail.login}`;
   278                  if (searchValue && !displayText.toLowerCase().includes(searchValue.toLowerCase())) {
   279                      return false;
   280                  }
   281
   282                  // Given the mention is inserted by user, we don't want to show the mention options unless the
   283                  // selection index changes. In that case, suggestionInsertionIndexRef.current will be null.
   284                  // See https://github.com/Expensify/App/issues/38358 for more context
   285                  if (suggestionInsertionIndexRef.current) {
   286                      return false;
   287                  }
   288
   289                  return true;
   290              }) as Array<PersonalDetails & {weight: number}>;
   291
   292              // At this point we are sure that the details are not null, since empty user details have been filtered in the previous step
   293              const sortedPersonalDetails = filteredPersonalDetails.sort(compareUserInList);
   294
   295              sortedPersonalDetails.slice(0, CONST.AUTO_COMPLETE_SUGGESTER.MAX_AMOUNT_OF_SUGGESTIONS - suggestions.length).forEach((detail) => {
   296                  suggestions.push({
   297                      text: formatLoginPrivateDomain(PersonalDetailsUtils.getDisplayNameOrDefault(detail), detail?.login),
   298                      alternateText: `@${formatLoginPrivateDomain(detail?.login, detail?.login)}`,
   299                      handle: detail?.login,
   300                      icons: [
   301                          {
   302                              name: detail?.login,
   303                              source: detail?.avatar ?? Expensicons.FallbackAvatar,
   304                              type: CONST.ICON_TYPE_AVATAR,
   305                              fallbackIcon: detail?.fallbackIcon,
   306                              id: detail?.accountID,
   307                          },
   308                      ],
   309                  });
   310              });
   311
   312              return suggestions;
   313          },
   314          [translate, formatPhoneNumber, formatLoginPrivateDomain],
   315      );
   316
   317      const getRoomMentionOptions = useCallback(
   318          (searchTerm: string, reportBatch: OnyxCollection<Report>): Mention[] => {
   319              const filteredRoomMentions: Mention[] = [];
   320              Object.values(reportBatch ?? {}).forEach((report) => {
   321                  if (!ReportUtils.canReportBeMentionedWithinPolicy(report, policyID ?? '-1')) {
   322                      return;
   323                  }
   324                  if (report?.reportName?.toLowerCase().includes(searchTerm.toLowerCase())) {
   325                      filteredRoomMentions.push({
   326                          text: report.reportName,
   327                          handle: report.reportName,
   328                          alternateText: report.reportName,
   329                      });
   330                  }
   331              });
   332
   333              return lodashSortBy(filteredRoomMentions, 'handle').slice(0, CONST.AUTO_COMPLETE_SUGGESTER.MAX_AMOUNT_OF_SUGGESTIONS);
   334          },
   335          [policyID],
   336      );
   337
   338      const calculateMentionSuggestion = useCallback(
   339          (newValue: string, selectionStart?: number, selectionEnd?: number) => {
   340              if (selectionEnd !== selectionStart || !selectionEnd || shouldBlockCalc.current || selectionEnd < 1 || !isComposerFocused) {
   341                  shouldBlockCalc.current = false;
   342                  resetSuggestions();
   343                  return;
   344              }
   345
   346              const afterLastBreakLineIndex = newValue.lastIndexOf('\n', selectionEnd - 1) + 1;
   347              const leftString = newValue.substring(afterLastBreakLineIndex, selectionEnd);
   348              const words = leftString.split(CONST.REGEX.SPACE_OR_EMOJI);
   349              const lastWord: string = words.at(-1) ?? '';
   350              const secondToLastWord = words[words.length - 3];
   351
   352              let atSignIndex: number | undefined;
   353              let suggestionWord = '';
   354              let prefix: string;
   355              let prefixType = '';
   356
   357              // Detect if the last two words contain a mention (two words are needed to detect a mention with a space in it)
   358              if (lastWord.startsWith('@') || lastWord.startsWith('#')) {
   359                  atSignIndex = leftString.lastIndexOf(lastWord) + afterLastBreakLineIndex;
   360                  suggestionWord = lastWord;
   361
   362                  prefix = suggestionWord.substring(1);
   363                  prefixType = suggestionWord.substring(0, 1);
   364              } else if (secondToLastWord && secondToLastWord.startsWith('@') && secondToLastWord.length > 1) {
   365                  atSignIndex = leftString.lastIndexOf(secondToLastWord) + afterLastBreakLineIndex;
   366                  suggestionWord = `${secondToLastWord} ${lastWord}`;
   367
   368                  prefix = suggestionWord.substring(1);
   369                  prefixType = suggestionWord.substring(0, 1);
   370              } else {
   371                  prefix = lastWord.substring(1);
   372              }
   373
   374              const nextState: Partial<SuggestionValues> = {
   375                  suggestedMentions: [],
   376                  atSignIndex,
   377                  mentionPrefix: prefix,
   378                  prefixType,
   379              };
   380
   381              if (isMentionCode(suggestionWord) && prefixType === '@') {
   382                  const suggestions = getUserMentionOptions(weightedPersonalDetails, prefix);
   383                  nextState.suggestedMentions = suggestions;
   384                  nextState.shouldShowSuggestionMenu = !!suggestions.length;
   385              }
   386
   387              const shouldDisplayRoomMentionsSuggestions = isGroupPolicyReport && (isValidRoomName(suggestionWord.toLowerCase()) || prefix === '');
   388              if (prefixType === '#' && shouldDisplayRoomMentionsSuggestions) {
   389                  // Filter reports by room name and current policy
   390                  nextState.suggestedMentions = getRoomMentionOptions(prefix, reports);
   391
   392                  // Even if there are no reports, we should show the suggestion menu - to perform live search
   393                  nextState.shouldShowSuggestionMenu = true;
   394              }
   395
   396              // Early return if there is no update
   397              const currentState = suggestionValuesRef.current;
   398              if (currentState.suggestedMentions.length === 0 && nextState.suggestedMentions?.length === 0) {
   399                  return;
   400              }
   401
   402              setSuggestionValues((prevState) => ({
   403                  ...prevState,
   404                  ...nextState,
   405              }));
   406              setHighlightedMentionIndex(0);
   407          },
   408          [isComposerFocused, isGroupPolicyReport, setHighlightedMentionIndex, resetSuggestions, getUserMentionOptions, weightedPersonalDetails, getRoomMentionOptions, reports],
   409      );
   410
   411      useEffect(() => {
   412          calculateMentionSuggestion(value, selection.start, selection.end);
   413      }, [value, selection, calculateMentionSuggestion]);
   414
   415      useEffect(() => {
   416          debouncedSearchInServer();
   417      }, [suggestionValues.suggestedMentions.length, suggestionValues.prefixType, policyID, value, debouncedSearchInServer]);
   418
   419      const updateShouldShowSuggestionMenuToFalse = useCallback(() => {
   420          setSuggestionValues((prevState) => {
   421              if (prevState.shouldShowSuggestionMenu) {
   422                  return {...prevState, shouldShowSuggestionMenu: false};
   423              }
   424              return prevState;
   425          });
   426      }, []);
   427
   428      const setShouldBlockSuggestionCalc = useCallback(
   429          (shouldBlockSuggestionCalc: boolean) => {
   430              shouldBlockCalc.current = shouldBlockSuggestionCalc;
   431          },
   432          [shouldBlockCalc],
   433      );
   434
   435      const getSuggestions = useCallback(() => suggestionValues.suggestedMentions, [suggestionValues]);
   436      const getIsSuggestionsMenuVisible = useCallback(() => isMentionSuggestionsMenuVisible, [isMentionSuggestionsMenuVisible]);
   437
   438      useImperativeHandle(
   439          ref,
   440          () => ({
   441              resetSuggestions,
   442              triggerHotkeyActions,
   443              setShouldBlockSuggestionCalc,
   444              updateShouldShowSuggestionMenuToFalse,
   445              getSuggestions,
   446              getIsSuggestionsMenuVisible,
   447          }),
   448          [resetSuggestions, setShouldBlockSuggestionCalc, triggerHotkeyActions, updateShouldShowSuggestionMenuToFalse, getSuggestions, getIsSuggestionsMenuVisible],
   449      );
   450
   451      if (!isMentionSuggestionsMenuVisible) {
   452          return null;
   453      }
   454
   455      return (
   456          <MentionSuggestions
   457              highlightedMentionIndex={highlightedMentionIndex}
   458              mentions={suggestionValues.suggestedMentions}
   459              prefix={suggestionValues.mentionPrefix}
   460              onSelect={insertSelectedMention}
   461              isMentionPickerLarge={!!isAutoSuggestionPickerLarge}
   462              measureParentContainerAndReportCursor={measureParentContainerAndReportCursor}
   463              resetSuggestions={resetSuggestions}
   464          />
   465      );
   466  }
   467
   468  SuggestionMention.displayName = 'SuggestionMention';
   469
   470  export default forwardRef(SuggestionMention);
   471
   472  export {compareUserInList};
